-- Import ONLY into the existing lendwhgp_salah_guard database. No CREATE DATABASE.
-- InnoDB; MySQL 5.7+/MariaDB 10.4+. No elevated privileges or stored procedures.
CREATE TABLE users (
 id CHAR(36) PRIMARY KEY, name VARCHAR(160) NOT NULL, email VARCHAR(254) NOT NULL UNIQUE,
 password_hash VARCHAR(255) NOT NULL, verified_at DATETIME NULL, dob DATE NULL,
 profile_file CHAR(36) NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE auth_sessions (
 id CHAR(36) PRIMARY KEY, user_id CHAR(36) NOT NULL, token_hash CHAR(64) NOT NULL UNIQUE,
 previous_hash CHAR(64) NULL, previous_until DATETIME NULL, expires_at DATETIME NOT NULL,
 created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,
 INDEX(user_id), INDEX(previous_hash), INDEX(expires_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE auth_actions (
 id CHAR(36) PRIMARY KEY, user_id CHAR(36) NOT NULL, kind VARCHAR(16) NOT NULL,
 token_hash CHAR(64) UNIQUE NOT NULL, expires_at DATETIME NOT NULL,
 FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE rate_limits (bucket CHAR(64) PRIMARY KEY,hits INT NOT NULL,reset_at BIGINT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE sync_changes (
 seq BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id CHAR(36) NOT NULL,entity VARCHAR(40) NOT NULL,
 record_id VARCHAR(150) NOT NULL, version INT NOT NULL,data JSON NOT NULL, deleted BOOLEAN NOT NULL DEFAULT FALSE,
 created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(user_id,seq),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE sync_operations (
 user_id CHAR(36) NOT NULL,id CHAR(36) NOT NULL,result JSON NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
 PRIMARY KEY(user_id,id), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE sync_tombstones (
 user_id CHAR(36) NOT NULL,entity VARCHAR(40) NOT NULL,record_id VARCHAR(150) NOT NULL,version INT NOT NULL,
 deleted_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(user_id,entity,record_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE user_settings (user_id CHAR(36) NOT NULL,id VARCHAR(150) NOT NULL,data JSON NOT NULL,version INT NOT NULL,deleted BOOLEAN NOT NULL DEFAULT FALSE,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,PRIMARY KEY(user_id,id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE prayer_records LIKE user_settings;
ALTER TABLE prayer_records ADD FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE;
CREATE TABLE qaza_records LIKE user_settings;
ALTER TABLE qaza_records ADD FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE;
CREATE TABLE routines LIKE user_settings;
ALTER TABLE routines ADD FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE;
CREATE TABLE routine_completions LIKE user_settings;
ALTER TABLE routine_completions ADD FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE;
CREATE TABLE tasbih_progress LIKE user_settings;
ALTER TABLE tasbih_progress ADD FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE;
CREATE TABLE routine_schedules (user_id CHAR(36) NOT NULL,routine_id VARCHAR(150) NOT NULL,data JSON NOT NULL,PRIMARY KEY(user_id,routine_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE streaks (user_id CHAR(36) NOT NULL,routine_id VARCHAR(150) NOT NULL,current_streak INT NOT NULL DEFAULT 0,best_streak INT NOT NULL DEFAULT 0,success_run INT NOT NULL DEFAULT 0,last_period VARCHAR(40) NULL,last_day DATE NULL,PRIMARY KEY(user_id,routine_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE freeze_wallets (user_id CHAR(36) PRIMARY KEY,balance INT NOT NULL DEFAULT 0,projection_key CHAR(64) NULL,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE freeze_transactions (id CHAR(36) PRIMARY KEY,user_id CHAR(36) NOT NULL,routine_id VARCHAR(150) NOT NULL,day DATE NOT NULL,kind VARCHAR(10) NOT NULL,delta INT NOT NULL,balance_after INT NOT NULL,UNIQUE(user_id,routine_id,day,kind),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE garden_progress (user_id CHAR(36) NOT NULL,routine_id VARCHAR(150) NOT NULL,stage INT NOT NULL DEFAULT 0,PRIMARY KEY(user_id,routine_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE user_files (id CHAR(36) PRIMARY KEY,user_id CHAR(36) NOT NULL,name VARCHAR(180) NOT NULL,mime VARCHAR(60) NOT NULL,bytes BIGINT NOT NULL,content_hash CHAR(64) NOT NULL,disk_name CHAR(64) NOT NULL UNIQUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,INDEX(user_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- DeenPath v0.3.0 additive migration. Back up first. Existing database only.
-- Safe to re-run; no existing tables, rows, credentials or identities are replaced.
CREATE TABLE IF NOT EXISTS schema_migrations (version VARCHAR(30) PRIMARY KEY, applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS qaza_history (user_id CHAR(36) NOT NULL,id VARCHAR(150) NOT NULL,data JSON NOT NULL,version INT NOT NULL,deleted BOOLEAN NOT NULL DEFAULT FALSE,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,PRIMARY KEY(user_id,id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS milestone_events (user_id CHAR(36) NOT NULL,id VARCHAR(150) NOT NULL,data JSON NOT NULL,version INT NOT NULL,deleted BOOLEAN NOT NULL DEFAULT FALSE,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,PRIMARY KEY(user_id,id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS learning_progress (user_id CHAR(36) NOT NULL,id VARCHAR(150) NOT NULL,data JSON NOT NULL,version INT NOT NULL,deleted BOOLEAN NOT NULL DEFAULT FALSE,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,PRIMARY KEY(user_id,id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS private_records (user_id CHAR(36) NOT NULL,id VARCHAR(150) NOT NULL,data JSON NOT NULL,version INT NOT NULL,deleted BOOLEAN NOT NULL DEFAULT FALSE,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,PRIMARY KEY(user_id,id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
